import{_ as o,o as t,c as d,a2 as l}from"./chunks/framework.BM5YPQmL.js";const _=JSON.parse('{"title":"端到端套件","description":"","frontmatter":{},"headers":[],"relativePath":"zh/dev/e2e-suites.md","filePath":"zh/dev/e2e-suites.md"}'),c={name:"zh/dev/e2e-suites.md"};function s(i,e,a,r,p,n){return t(),d("div",null,[...e[0]||(e[0]=[l('<h1 id="端到端套件" tabindex="-1">端到端套件 <a class="header-anchor" href="#端到端套件" aria-label="Permalink to &quot;端到端套件&quot;">​</a></h1><p>为发布把关的深度测试。它们全部通过 pexpect 在串口控制台上 驱动一次真实的 QEMU 启动；下表是发布证据所引用的矩阵 （真实输出、声明的跳过计数）。CI 本身只做构建 —— 这些在 本地/发布时运行（<code>tools/build_release.sh --deep</code>）。</p><h2 id="_1-验证矩阵" tabindex="-1">1. 验证矩阵 <a class="header-anchor" href="#_1-验证矩阵" aria-label="Permalink to &quot;1. 验证矩阵&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>门禁</th><th>工具</th><th>必须打印的行</th></tr></thead><tbody><tr><td>1</td><td>宿主单元测试（<code>make test</code>）</td><td><code>tools/run_host_tests.py</code></td><td>所有套件 PASS（SKIP-FIXTURE 已声明）</td></tr><tr><td>2</td><td>完整回归 31/31</td><td><code>tools/run_fix4_regression.py</code></td><td><code>=== 31/31 checks passed</code></td></tr><tr><td>3</td><td>SSH E2E</td><td><code>tools/ssh_g11a_e2e.py</code></td><td><code>[g11a] ALL PASS</code>（5 项检查）</td></tr><tr><td>4</td><td>HTTPS E2E</td><td><code>tools/run_fix4_https_e2e.py</code></td><td><code>=== 8/8 HTTPS E2E checks passed</code></td></tr><tr><td>5</td><td>看门狗/日志/健康</td><td><code>tools/wp12_watchdog_logging_e2e.py</code></td><td>S1-S14</td></tr><tr><td>6</td><td>TUI / 中文 / 桌面</td><td><code>tools/wp10_*.py</code></td><td>按套件</td></tr><tr><td>7</td><td>mega 应用冒烟</td><td>WP-l1apps-merge 冒烟脚本</td><td>21/21</td></tr></tbody></table><h2 id="_2-回归门禁-——-全部-31-项检查" tabindex="-1">2. 回归门禁 —— 全部 31 项检查 <a class="header-anchor" href="#_2-回归门禁-——-全部-31-项检查" aria-label="Permalink to &quot;2. 回归门禁 —— 全部 31 项检查&quot;">​</a></h2><p><code>tools/run_fix4_regression.py</code> 启动 ISO（512M、 <code>-serial mon:stdio</code>、e1000 user 网络、供帧缓冲断言使用的 HMP monitor unix socket），等待 <code>ush&gt;</code>，运行 24 条命令， 然后检查。每个模式都限定在唯一一条命令的输出分节内 （BUG #64 修复：全日志匹配在结构上永远为真），并剥离回显 的命令行，使含名字的模式永远无法自欺满足。</p><p><strong>启动组（6）</strong></p><ol><li>屏幕帧缓冲存活（BUG #66）—— HMP 截屏，&gt;= 2 种颜色 + 可测的前景比例（仅看串口的门禁曾在死面板上通过）</li><li>启动横幅就绪 —— <code>Open Cube OS User-space Shell \\(3\\.0\\.0</code></li><li>启动提示 —— <code>Type &#39;help&#39; for built-in commands</code></li><li>启动完成 OK —— <code>boot complete\\.+ OK</code></li><li>异常自检 3/3</li><li>命令数 &gt;= 276 —— 从 <code>help -a</code> 注册表行动态统计 （WP-l1apps-merge 树上实测 <strong>284</strong>）；接口冻结下限</li></ol><p><strong>系统组（2）</strong></p><ol start="7"><li>uname 当前树 —— 版本正则，含 WP-10/11/12/13/14 标记</li><li>crashlog 干净启动 —— <code>no exceptions recorded|0 entries|N entries</code></li></ol><p><strong>自检程序组（17）</strong></p><ol start="9"><li>heaptest 通过 —— <code>\\bPASS\\b</code></li><li>fstest 通过 —— <code>VFS self-test.*PASS</code></li><li>cryptotest NIST 通过</li><li>l1test wp8b 加载器 14/14 —— <code>ext_wp8b selftest 14/14 - PASS</code></li><li>l1test 作业步骤 PASS</li><li>l1test 总体 PASS</li><li>hello 输出</li><li>fork_test</li><li>exec_test</li><li>pipe_test</li><li>signal_test</li><li>select_test</li><li>mmap_test</li><li>mmap_multi</li><li>g7mmap（BUG-0281）</li><li>p3_test（优先级）</li><li>g6_test 全链 —— 异步汇总 <code>failed tests = 0</code> （单独等待 300 秒）</li></ol><p><strong>动态链接组（5）</strong></p><ol start="26"><li>dyn_hello —— <code>hello from dynamic program</code></li><li>so_test —— <code>foo_add(2,3)=5</code></li><li>dlsym_test —— <code>foo_add(7,8)=15</code></li><li>pie_test —— <code>loaded at 0x...</code></li><li>reloc_test —— <code>foo_add=30 foo_global=42 fp=300</code></li></ol><p><strong>安全组（1）</strong></p><ol start="31"><li>p0leak 围栏通过 —— <code>all kernel-address probes fenced</code></li></ol><p>退出码 = 失败检查数；发布矩阵引用 31/31。</p><h2 id="_3-ssh-e2e-5-5-——-tools-ssh-g11a-e2e-py" tabindex="-1">3. SSH E2E（5/5）—— tools/ssh_g11a_e2e.py <a class="header-anchor" href="#_3-ssh-e2e-5-5-——-tools-ssh-g11a-e2e-py" aria-label="Permalink to &quot;3. SSH E2E（5/5）—— tools/ssh_g11a_e2e.py&quot;">​</a></h2><p>方向 A（客户机客户端 -&gt; 宿主 :2222 上的 <code>tools/paramiko_sshd.py</code>）：</p><ol><li><code>ssh-auth</code> —— <code>[ssh] authenticated (USERAUTH_SUCCESS)</code></li><li><code>ssh-exec</code> —— <code>[ssh] exec output: hello-from-OpenCubeOS-kernel-ssh</code></li></ol><p>方向 B（客户机 <code>sshd 22 oc oc</code> &lt;- 宿主 paramiko 客户端， 经 hostfwd tcp::2223-:22）：</p><ol start="3"><li><code>sshd-listen</code> —— <code>listening on port 22</code></li><li><code>sshd-exec</code> —— 客户端 <code>uname</code> 返回 <code>Open Cube OS</code></li><li><code>sshd-capture-log</code> —— <code>exec: captured N bytes of output</code></li></ol><p>固化在工具里的运维要点：</p><ul><li>TCG 下 RSA-2048 密钥生成 &gt; 500 秒 —— 用 <code>tools/host_keygen_etc.py</code> 把宿主密钥（n||d，各 256 字节， e=65537）预播种进 <code>build/etc.img</code>；加载器走&quot;密钥已在 磁盘上&quot;的快速路径（<code>OC_ETC_IMG</code> 选择预播种镜像）。</li><li>宽裕的 paramiko 超时（横幅 420 秒）—— TCG 下每个握手 阶段都要花几十秒。</li><li>在服务器测试之前用一个客户端方向的包预热 ARP 缓存 （冷缓存 SYN-ACK 停滞）。</li></ul><h2 id="_4-https-e2e-8-8-——-tools-run-fix4-https-e2e-py" tabindex="-1">4. HTTPS E2E（8/8）—— tools/run_fix4_https_e2e.py <a class="header-anchor" href="#_4-https-e2e-8-8-——-tools-run-fix4-https-e2e-py" aria-label="Permalink to &quot;4. HTTPS E2E（8/8）—— tools/run_fix4_https_e2e.py&quot;">​</a></h2><p>针对 <code>tools/https_test_server.py</code>（与内核客户端匹配的 单请求 OpenSSL 服务器：仅 TLS 1.2、0x0067 DHE-RSA-AES128-SHA256、1024 位 RFC 3526 DH、自签名； <code>observe</code> 模式 = 原始字节 close_notify 记录器；<code>eof</code> 模式 = 硬关闭截断服务器）：</p><ol start="0"><li><strong>自签名链默认被拒绝</strong>（BUG #21 验收）—— <code>config set tls.insecure 1</code> 是兼容性轮次所用的显式 选择加入</li><li>TLS 握手 —— 内核日志 <code>Connecting ... (TLS)</code></li><li>协商出 TLS 1.2 + 密码套件 DHE-RSA-AES128-SHA256 （0x0067）（服务器侧）</li><li>收到加密的 <code>GET /hello.txt</code>（服务器侧）</li><li>提供规范正文（<code>body=24</code>）</li><li>内核保存了正文（<code>wget</code> + <code>cat /wget_https.html</code> 匹配）</li><li>观察到内核 close_notify（原始字节记录器模式）</li><li><strong>截断守卫</strong> —— 硬关闭服务器（<code>eof</code> 模式）让内核 迅速失败（&lt; 45 秒，错误文本）而不是挂起</li></ol><p>证书/DH 夹具在运行中生成：openssl 自签名 RSA-2048 + 钉在 RFC 3526 1024 位 MODP 组上的 DH 参数（由服务器 自身的 <code>P_HEX</code> 以 ASN.1 构造）。</p><h2 id="_5-mega-应用冒烟-21-21" tabindex="-1">5. mega 应用冒烟（21/21） <a class="header-anchor" href="#_5-mega-应用冒烟-21-21" aria-label="Permalink to &quot;5. mega 应用冒烟（21/21）&quot;">​</a></h2><p>阶段 A —— 经典分发字节兼容：<code>disk-tool lsblk</code>、 <code>net-tool ip</code>、<code>sound-tool sound</code>、<code>sysdiag health</code>、 <code>hwinfo uname</code>、<code>power sleep 1</code>、<code>files df</code>、 <code>update status</code>、<code>disk-tool direct lsblk</code>，以及未知 op 的用法行。</p><p>阶段 B —— 向导：每个应用的无参菜单都能渲染并在 <code>q</code> 上退出；<code>disk-tool</code> 经菜单键 1 + ENTER 暂停运行 lsblk； <code>update</code> 真实走完步骤 1-2（网络检查、A/B 缺席处理）并 干净地返回 ush。</p><p>注意：树中没有提交 <code>tools/test_megaapps.py</code> —— 冒烟 装置以&quot;WP-l1apps-merge 冒烟脚本&quot;的名义被引用（发布说明 中引用 21/21）；复现该矩阵的维护者按上面的阶段 A/B 清单重新搭建它。</p><h2 id="_6-宿主单元测试-——-tools-run-host-tests-py" tabindex="-1">6. 宿主单元测试 —— tools/run_host_tests.py <a class="header-anchor" href="#_6-宿主单元测试-——-tools-run-host-tests-py" aria-label="Permalink to &quot;6. 宿主单元测试 —— tools/run_host_tests.py&quot;">​</a></h2><p>各套件在宿主侧编译 L0 组件并运行：multiboot2 解析器 （ASAN）、加密（NIST AES/SHA/HMAC、RSA、X.509、AEAD）、 对照 RFC 8448 的 TLS 1.3 密钥调度、TCP 拥塞控制 （CUBIC）、block-512 门禁，以及各子系统电池（BT、WiFi、 相机、SCSI、IR、触摸板）。SKIP-FIXTURE 套件在 openssl 夹具存在时真实运行 —— 状态永远被声明。完整清单： <a href="./host-tests.html">host-tests.md</a>。</p><h2 id="_7-看门狗-tui-中文套件" tabindex="-1">7. 看门狗 / TUI / 中文套件 <a class="header-anchor" href="#_7-看门狗-tui-中文套件" aria-label="Permalink to &quot;7. 看门狗 / TUI / 中文套件&quot;">​</a></h2><p><code>tools/wp12_watchdog_logging_e2e.py</code> —— 14 个场景 S1-S14：klog 级别/开关、logcat 过滤器、dmesg 回放、 logctl、持久化 + 轮转 <code>.1</code> 链、全局过滤器、 <strong>S12：Intel TCO 真实复位 + 第二次启动</strong>（q35、 <code>-no-reboot</code>、发现、布防、饿死、断言第二次启动）、 <strong>S13：ACPI WDAT</strong>（用 <code>tools/make_wdat_table.py</code> 合成 但合法的 WDAT 表经 <code>-acpitable</code> 注入，驱动真实 q35 TCO 寄存器）、策略 kill、健康 JSON。</p><p><code>tools/wp10_*.py</code> —— TUI/中文/桌面/芯片组/定时器/ 无线/相机家族；人工验证者把抖动的检查作为隔离的全新 QEMU 场景重跑（QEMU 在 HMP 截屏后丢弃串口 RX 字节 —— 已用内核内 RX trace 验证；因此功能轮次从不截图）。</p><h2 id="_8-pexpect-机制与串口回显容忍" tabindex="-1">8. pexpect 机制与串口回显容忍 <a class="header-anchor" href="#_8-pexpect-机制与串口回显容忍" aria-label="Permalink to &quot;8. pexpect 机制与串口回显容忍&quot;">​</a></h2><p>每个套件继承的共享模式（<code>tools/qemu_runner.py</code>）：</p><ul><li><code>pexpect.spawn(QEMU, [...], encoding=&quot;latin-1&quot;, codec_errors=&quot;replace&quot;)</code> —— 用 latin-1 让每个字节都 存活；正则之前剥离 NUL。</li><li>提示符正则 <code>(?:ush&gt;|oc&gt;)\\s</code>（可用 <code>OC_PROMPT</code> 覆盖）； v2 流程适配器 <code>boot_to_recovery()</code> 在 <code>ush&gt;</code> 处发送 <code>exit</code> 以到达 <code>oc&gt;</code> 恢复提示符。</li><li><code>strip_ansi()</code> 在匹配前移除 CSI 序列。</li><li><strong>串口回显容忍</strong> —— &quot;ega]&quot; 现象：当客户机回显输入的 命令时，回显可能与同一命令的<em>输出</em>重叠，吃掉 <code>[tag]</code> 括号的前导 <code>&quot;e&quot;</code>，因此 <code>gen_api_docs.py</code> 把 <code>[tag]</code> 括号当作可选，而回归门禁把每个模式限定在其自己的命令 分节并先剥离回显行。</li><li>串口链路无法承载的按键（方向键/Home/End）经 HMP monitor 的 <code>sendkey</code> 送入；指针输入经 QMP <code>input-send-event</code>（<code>-display none</code> + QEMU 10 上 HMP mouse_move 已失效）；截屏经 unix monitor socket 上的 HMP <code>screendump</code>；控制字节必须原样到达时用 unix-socket chardev 走原始串口。</li><li>已知的抖动来源：QEMU 在 HMP 截屏后间歇性丢弃串口 RX -&gt; 功能轮次从不截图；抖动的检查被隔离重跑 （<code>wp10_native_manual.py</code>）。</li></ul>',40)])])}const u=o(c,[["render",s]]);export{_ as __pageData,u as default};
